import { INTERNAL_ERROR, INVALID_PARAMS, INVALID_REQUEST, METHOD_NOT_FOUND } from '@mokei/context-protocol';
export class RPCError extends Error {
    static fromResponse(response) {
        return new RPCError(response.error.code, response.error.message, response.error.data);
    }
    #code;
    #data;
    constructor(code, message, data){
        super(message);
        this.#code = code;
        this.#data = data;
    }
    get code() {
        return this.#code;
    }
    get data() {
        return this.#data;
    }
    get isInternal() {
        return this.code === INTERNAL_ERROR;
    }
    get isInvalidParams() {
        return this.code === INVALID_PARAMS;
    }
    get isInvalidRequest() {
        return this.code === INVALID_REQUEST;
    }
    get isMethodNotFound() {
        return this.code === METHOD_NOT_FOUND;
    }
    toResponse(id) {
        return {
            jsonrpc: '2.0',
            id,
            error: {
                code: this.#code,
                message: this.message,
                data: this.#data
            }
        };
    }
}
export function errorResponse(id, cause) {
    if (cause instanceof RPCError) {
        return cause.toResponse(id);
    }
    const message = cause instanceof Error ? cause.message : typeof cause === 'string' ? cause : 'Unknown error';
    return {
        jsonrpc: '2.0',
        id,
        error: {
            code: INTERNAL_ERROR,
            message
        }
    };
}
